type ActiveModal = null | 'reset' | 'register' | 'legal' | 'contact';

function maskPhone(raw: string): string {
  const digits = raw.replace(/\D/g, '');
  if (digits.length === 11) {
    return `${digits.slice(0, 3)} •••• ${digits.slice(7)}`;
  }
  return raw;
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

export function mountLoginView(
  root: HTMLElement,
  adapter: PacomDataAdapter,
  onAuthenticated: (session: UserSession) => void
): void {
  root.classList.add('bare-login');
  document.title = '登录 · PACOM Station';

  let smsMode = false;
  let showPwd = false;
  let accountVal = '';
  let pwdVal = '';
  let phoneVal = '';
  let codeVal = '';
  let keepLogin = false;

  let fieldErrors: Record<string, string> = {};
  let formError = '';
  let busy = false;

  let smsSentTo = '';
  let smsCooldown = 0;
  let smsTimer: number | null = null;

  let activeModal: ActiveModal = null;
  let legalTab: 'privacy' | 'terms' | 'service' = 'privacy';
  let copyNotice = '';
  let resetAccount = '';
  let resetNotice = '';

  function cleanup(): void {
    if (smsTimer !== null) {
      window.clearInterval(smsTimer);
      smsTimer = null;
    }
    root.classList.remove('bare-login');
  }

  function startCooldown(): void {
    smsCooldown = 60;
    if (smsTimer !== null) window.clearInterval(smsTimer);
    smsTimer = window.setInterval(() => {
      smsCooldown -= 1;
      if (smsCooldown <= 0) {
        smsCooldown = 0;
        if (smsTimer !== null) {
          window.clearInterval(smsTimer);
          smsTimer = null;
        }
      }
      const btn = root.querySelector<HTMLButtonElement>('[data-act="send-sms"]');
      if (btn) {
        btn.disabled = smsCooldown > 0;
        btn.textContent = smsCooldown > 0 ? `${smsCooldown} 秒后重发` : smsSentTo ? '重新获取' : '获取验证码';
      }
    }, 1000);
  }

  function renderModal(): string {
    if (!activeModal) return '';

    if (activeModal === 'reset') {
      return `
        <div class="au-account-scrim" data-role="modal-scrim">
          <section class="au-account-dlg au-reset-dlg" role="dialog" aria-modal="true" aria-labelledby="au-dlg-title">
            <div class="dh">
              <h2 id="au-dlg-title">重置密码</h2>
              <button type="button" class="au-dlg-close" data-act="close-modal" aria-label="关闭">${CLOSE_SVG}</button>
            </div>
            <div class="db">
              <p class="au-dlead">输入注册时使用的电子邮箱或手机号码，验证后即可设置新密码并登录。</p>
              <form id="au-reset-form" novalidate>
                <div class="au-field">
                  <div class="au-lab"><label for="au-rs-id">电子邮箱或手机号码</label></div>
                  <div class="au-ctl">
                    <input id="au-rs-id" name="rs_id" class="au-in" type="text" autocomplete="username" value="${escapeHtml(resetAccount)}" />
                  </div>
                </div>
                ${resetNotice ? `<p class="au-hint" style="margin-top:8px; color:#202a44;">${escapeHtml(resetNotice)}</p>` : ''}
              </form>
            </div>
            <div class="df">
              <button type="button" class="au-dlg-btn au-dlg-btn--ghost" data-act="close-modal">取消</button>
              <button type="submit" form="au-reset-form" class="au-dlg-btn au-dlg-btn--primary">发送验证码</button>
            </div>
          </section>
        </div>
      `;
    }

    if (activeModal === 'register') {
      return `
        <div class="au-account-scrim" data-role="modal-scrim">
          <section class="au-account-dlg" role="dialog" aria-modal="true" aria-labelledby="au-dlg-title">
            <div class="dh">
              <h2 id="au-dlg-title">注册个人账户</h2>
              <button type="button" class="au-dlg-close" data-act="close-modal" aria-label="关闭">${CLOSE_SVG}</button>
            </div>
            <div class="db">
              <p class="au-dlead">PACOM Station 按机构开通使用。注册后可凭所在机构的 9 位邀请码申请加入，或直接创建新机构。</p>
              <p class="au-dlead" style="margin-bottom:0;">
                请联系所在机构管理员获取邀请码，或通过支持邮箱联系开通新机构账户。
              </p>
            </div>
            <div class="df">
              <button type="button" class="au-dlg-btn au-dlg-btn--ghost" data-act="close-modal">关闭</button>
            </div>
          </section>
        </div>
      `;
    }

    if (activeModal === 'legal') {
      const current = LEGAL_DOCS[legalTab];
      const legalTabsHtml = (['privacy', 'terms', 'service'] as const)
        .map(
          (key) =>
            `<button type="button" role="tab" aria-selected="${legalTab === key}" class="au-legal-tab ${legalTab === key ? 'is-active' : ''}" data-act="switch-legal" data-tab="${key}">${LEGAL_DOCS[key].title}</button>`
        )
        .join('');
      return `
        <div class="au-account-scrim" data-role="modal-scrim">
          <section class="au-account-dlg" role="dialog" aria-modal="true" aria-labelledby="au-dlg-title">
            <div class="dh">
              <h2 id="au-dlg-title">隐私和法律</h2>
              <button type="button" class="au-dlg-close" data-act="close-modal" aria-label="关闭">${CLOSE_SVG}</button>
            </div>
            <div class="db">
              <div class="au-legal-tabs" role="tablist">
                ${legalTabsHtml}
              </div>
              <p style="margin:0 0 12px; color:#636363; font-size:12px;">2026 年 9 月 1 日起生效</p>
              <ul class="au-legal-list">
                ${current.items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}
              </ul>
            </div>
            <div class="df">
              <button type="button" class="au-dlg-btn au-dlg-btn--ghost" data-act="close-modal">关闭</button>
            </div>
          </section>
        </div>
      `;
    }

    if (activeModal === 'contact') {
      return `
        <div class="au-account-scrim" data-role="modal-scrim">
          <section class="au-account-dlg" role="dialog" aria-modal="true" aria-labelledby="au-dlg-title">
            <div class="dh">
              <h2 id="au-dlg-title">联系我们</h2>
              <button type="button" class="au-dlg-close" data-act="close-modal" aria-label="关闭">${CLOSE_SVG}</button>
            </div>
            <div class="db">
              <p class="au-dlead">如需账号协助、机构开通或技术支持，请通过以下邮箱联系 PACOM 支持团队。</p>
              <div class="au-support-row">
                <a href="mailto:support@pacom.cn">support@pacom.cn</a>
                <button type="button" class="au-dlg-btn au-dlg-btn--ghost" style="height:28px; padding:0 10px; font-size:12px;" data-act="copy-support">
                  ${copyNotice || '复制邮箱'}
                </button>
              </div>
              <p style="margin:0; color:#636363; font-size:12px;">广州天环智能技术有限公司</p>
            </div>
            <div class="df">
              <button type="button" class="au-dlg-btn au-dlg-btn--ghost" data-act="close-modal">关闭</button>
            </div>
          </section>
        </div>
      `;
    }

    return '';
  }

  function render(): void {
    const idFieldHtml = smsMode
      ? `
        <div class="au-field ${fieldErrors.sphone ? 'bad' : ''}" data-f="sphone">
          <div class="au-lab"><label for="au-sphone">手机号码</label></div>
          <div class="au-ctl">
            <input id="au-sphone" name="sphone" class="au-in has-code-btn" type="tel" inputmode="tel" autocomplete="tel" autocapitalize="none" autocorrect="off" spellcheck="false" value="${escapeHtml(phoneVal)}" aria-invalid="${fieldErrors.sphone ? 'true' : 'false'}" />
            <button type="button" class="au-suffix au-getcode" data-act="send-sms" ${smsCooldown > 0 ? 'disabled' : ''}>
              ${smsCooldown > 0 ? `${smsCooldown} 秒后重发` : smsSentTo ? '重新获取' : '获取验证码'}
            </button>
          </div>
          <p class="au-err" id="au-sphone-err" aria-live="polite">${escapeHtml(fieldErrors.sphone ?? '')}</p>
          <p class="au-hint" id="au-sphone-hint" role="status" aria-live="polite">${smsSentTo ? `验证码已发送至 ${escapeHtml(maskPhone(smsSentTo))}` : ''}</p>
        </div>
      `
      : `
        <div class="au-field ${fieldErrors.id ? 'bad' : ''}" data-f="id">
          <div class="au-lab"><label for="au-id">电子邮箱或手机号码</label></div>
          <div class="au-ctl">
            <input id="au-id" name="id" class="au-in" type="text" autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" value="${escapeHtml(accountVal)}" aria-invalid="${fieldErrors.id ? 'true' : 'false'}" />
          </div>
          <p class="au-err" id="au-id-err" aria-live="polite">${escapeHtml(fieldErrors.id ?? '')}</p>
        </div>
      `;

    const secretFieldHtml = smsMode
      ? `
        <div class="au-field ${fieldErrors.scode ? 'bad' : ''}" data-f="scode">
          <div class="au-lab"><label for="au-scode">短信验证码</label></div>
          <div class="au-ctl">
            <input id="au-scode" name="scode" class="au-in" type="text" inputmode="numeric" autocomplete="one-time-code" maxlength="6" autocapitalize="none" autocorrect="off" spellcheck="false" value="${escapeHtml(codeVal)}" aria-invalid="${fieldErrors.scode ? 'true' : 'false'}" />
          </div>
          <p class="au-err" id="au-scode-err" aria-live="polite">${escapeHtml(fieldErrors.scode ?? '')}</p>
        </div>
      `
      : `
        <div class="au-field au-field-right-after ${fieldErrors.pwd ? 'bad' : ''}" data-f="pwd">
          <div class="au-lab"><label for="au-pwd">密码</label></div>
          <div class="au-ctl">
            <input id="au-pwd" name="pwd" class="au-in has-suffix" type="${showPwd ? 'text' : 'password'}" autocomplete="current-password" autocapitalize="none" autocorrect="off" spellcheck="false" value="${escapeHtml(pwdVal)}" aria-invalid="${fieldErrors.pwd ? 'true' : 'false'}" />
            <button type="button" class="au-suffix au-eye" data-act="toggle-eye" aria-controls="au-pwd" aria-label="${showPwd ? '隐藏密码' : '显示密码'}">
              ${showPwd ? EYE_OPEN_SVG : EYE_CLOSED_SVG}
            </button>
          </div>
          <div class="au-field-right">
            <button type="button" class="au-textbtn au-login-forgot" data-act="open-reset"><span>忘记密码？</span></button>
          </div>
          <p class="au-err" id="au-pwd-err" aria-live="polite">${escapeHtml(fieldErrors.pwd ?? '')}</p>
        </div>
      `;

    root.innerHTML = `
      <div class="au au-split au-auth-shell">
        <section class="au-left">
          <div class="au-center">
            <main class="au-group">
              <div class="au-logo">${PACOM_LOGO_SVG}</div>
              <h1 class="au-h1">登录</h1>
              <form class="au-compact-form" data-form="login" novalidate>
                <fieldset ${busy ? 'disabled' : ''}>
                  ${idFieldHtml}
                  ${secretFieldHtml}
                  <p class="au-ferr" id="au-login-ferr" role="alert" ${formError ? '' : 'hidden'}>${escapeHtml(formError)}</p>
                  <label class="au-check au-keep-login" data-f="keep">
                    <input type="checkbox" name="keep" ${keepLogin ? 'checked' : ''} />
                    <span>30 天内保持登录</span>
                  </label>
                  <button type="submit" class="au-primary au-compact-primary" ${busy ? 'disabled' : ''}>
                    ${busy ? '正在登录…' : '登录'}
                  </button>
                </fieldset>
              </form>
              <div class="au-login-actions">
                <button type="button" class="au-textbtn" data-act="toggle-sms">
                  <span>${smsMode ? '使用密码登录' : '使用短信验证码登录'}</span>
                </button>
                <div class="au-login-divider" aria-hidden="true"></div>
                <p class="au-noacct">
                  没有账户？<button type="button" class="au-inline" data-act="open-register">注册</button>
                </p>
              </div>
            </main>
          </div>
          <footer class="au-foot" aria-label="版权、法律与联系信息">
            <span class="au-copyright">© 2026 广州天环智能技术有限公司</span>
            <div class="au-foot-links">
              <button type="button" data-act="open-legal">隐私和法律</button>
              <button type="button" data-act="open-contact">联系我们</button>
            </div>
          </footer>
        </section>
        <aside class="au-art" aria-hidden="true">
          <img src="./media/auth-hero.jpg" alt="" />
        </aside>
      </div>
      ${renderModal()}
    `;

    bindEvents();
  }

  function bindEvents(): void {
    const idInput = root.querySelector<HTMLInputElement>('#au-id');
    const pwdInput = root.querySelector<HTMLInputElement>('#au-pwd');
    const phoneInput = root.querySelector<HTMLInputElement>('#au-sphone');
    const codeInput = root.querySelector<HTMLInputElement>('#au-scode');
    const keepInput = root.querySelector<HTMLInputElement>('input[name="keep"]');

    idInput?.addEventListener('input', () => {
      accountVal = idInput.value;
      if (fieldErrors.id || formError) {
        delete fieldErrors.id;
        formError = '';
        idInput.closest('.au-field')?.classList.remove('bad');
        const errEl = root.querySelector('#au-id-err');
        if (errEl) errEl.textContent = '';
        const ferrEl = root.querySelector<HTMLElement>('#au-login-ferr');
        if (ferrEl) ferrEl.hidden = true;
      }
    });

    pwdInput?.addEventListener('input', () => {
      pwdVal = pwdInput.value;
      if (fieldErrors.pwd || formError) {
        delete fieldErrors.pwd;
        formError = '';
        pwdInput.closest('.au-field')?.classList.remove('bad');
        const errEl = root.querySelector('#au-pwd-err');
        if (errEl) errEl.textContent = '';
        const ferrEl = root.querySelector<HTMLElement>('#au-login-ferr');
        if (ferrEl) ferrEl.hidden = true;
      }
    });

    phoneInput?.addEventListener('input', () => {
      phoneVal = phoneInput.value;
      if (fieldErrors.sphone || formError) {
        delete fieldErrors.sphone;
        formError = '';
        phoneInput.closest('.au-field')?.classList.remove('bad');
        const errEl = root.querySelector('#au-sphone-err');
        if (errEl) errEl.textContent = '';
        const ferrEl = root.querySelector<HTMLElement>('#au-login-ferr');
        if (ferrEl) ferrEl.hidden = true;
      }
    });

    codeInput?.addEventListener('input', () => {
      codeVal = codeInput.value.replace(/\D/g, '').slice(0, 6);
      codeInput.value = codeVal;
      if (fieldErrors.scode || formError) {
        delete fieldErrors.scode;
        formError = '';
        codeInput.closest('.au-field')?.classList.remove('bad');
        const errEl = root.querySelector('#au-scode-err');
        if (errEl) errEl.textContent = '';
        const ferrEl = root.querySelector<HTMLElement>('#au-login-ferr');
        if (ferrEl) ferrEl.hidden = true;
      }
    });

    keepInput?.addEventListener('change', () => {
      keepLogin = keepInput.checked;
    });

    root.querySelector<HTMLButtonElement>('[data-act="toggle-eye"]')?.addEventListener('click', () => {
      showPwd = !showPwd;
      render();
      const nextPwd = root.querySelector<HTMLInputElement>('#au-pwd');
      nextPwd?.focus();
    });

    root.querySelector<HTMLButtonElement>('[data-act="toggle-sms"]')?.addEventListener('click', () => {
      smsMode = !smsMode;
      fieldErrors = {};
      formError = '';
      render();
      const target = root.querySelector<HTMLInputElement>(smsMode ? '#au-sphone' : '#au-id');
      target?.focus();
    });

    root.querySelector<HTMLButtonElement>('[data-act="send-sms"]')?.addEventListener('click', () => {
      const cleaned = phoneVal.trim();
      if (!/^(\+?\d[\d\s-]{6,18})$/.test(cleaned)) {
        fieldErrors = { sphone: '请输入有效的手机号码' };
        render();
        root.querySelector<HTMLInputElement>('#au-sphone')?.focus();
        return;
      }
      fieldErrors = {};
      smsSentTo = cleaned;
      startCooldown();
      render();
      root.querySelector<HTMLInputElement>('#au-scode')?.focus();
    });

    root.querySelector<HTMLFormElement>('form[data-form="login"]')?.addEventListener('submit', async (e) => {
      e.preventDefault();
      if (busy) return;
      fieldErrors = {};
      formError = '';

      if (smsMode) {
        if (!phoneVal.trim()) fieldErrors.sphone = '请输入手机号码';
        if (!/^\d{6}$/.test(codeVal.trim())) fieldErrors.scode = '请输入 6 位验证码';
      } else {
        if (!accountVal.trim()) fieldErrors.id = '请输入电子邮箱或手机号码';
        if (!pwdVal) fieldErrors.pwd = '请输入密码';
      }

      if (Object.keys(fieldErrors).length > 0) {
        render();
        const firstKey = Object.keys(fieldErrors)[0];
        root.querySelector<HTMLInputElement>(`#au-${firstKey}`)?.focus();
        return;
      }

      busy = true;
      render();
      try {
        const session = await adapter.login({
          account: (smsMode ? phoneVal : accountVal).trim(),
          password: smsMode ? codeVal.trim() : pwdVal,
        });
        cleanup();
        onAuthenticated(session);
      } catch (err) {
        busy = false;
        formError = err instanceof Error ? err.message : '账户或密码不正确';
        render();
      }
    });

    root.querySelector<HTMLButtonElement>('[data-act="open-reset"]')?.addEventListener('click', () => {
      resetAccount = accountVal.trim();
      resetNotice = '';
      activeModal = 'reset';
      render();
      root.querySelector<HTMLInputElement>('#au-rs-id')?.focus();
    });

    root.querySelector<HTMLButtonElement>('[data-act="open-register"]')?.addEventListener('click', () => {
      activeModal = 'register';
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-act="open-legal"]')?.addEventListener('click', () => {
      activeModal = 'legal';
      render();
    });

    root.querySelector<HTMLButtonElement>('[data-act="open-contact"]')?.addEventListener('click', () => {
      copyNotice = '';
      activeModal = 'contact';
      render();
    });

    root.querySelectorAll<HTMLButtonElement>('[data-act="close-modal"]').forEach((btn) => {
      btn.addEventListener('click', () => {
        activeModal = null;
        render();
      });
    });

    root.querySelector<HTMLElement>('[data-role="modal-scrim"]')?.addEventListener('click', (e) => {
      if (e.target === e.currentTarget) {
        activeModal = null;
        render();
      }
    });

    root.querySelectorAll<HTMLButtonElement>('[data-act="switch-legal"]').forEach((btn) => {
      btn.addEventListener('click', () => {
        const tab = btn.dataset.tab as 'privacy' | 'terms' | 'service' | undefined;
        if (tab) {
          legalTab = tab;
          render();
        }
      });
    });

    root.querySelector<HTMLButtonElement>('[data-act="copy-support"]')?.addEventListener('click', async () => {
      try {
        await navigator.clipboard.writeText('support@pacom.cn');
        copyNotice = '已复制';
      } catch {
        copyNotice = 'support@pacom.cn';
      }
      render();
    });

    root.querySelector<HTMLFormElement>('#au-reset-form')?.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = root.querySelector<HTMLInputElement>('#au-rs-id');
      resetAccount = input?.value.trim() ?? '';
      if (!resetAccount) {
        resetNotice = '请输入电子邮箱或手机号码';
      } else {
        resetNotice = '请联系机构管理员重置账号密码，或确认后查收重置邮件。';
      }
      render();
    });

  }

  render();
}
