  async copyZonesToFloors(sourceFloorId: string, targetFloorIds: string[]): Promise<number> {
    const session = this.requireSession();
    if (!session.scope.canEditDeployment) throw new Error(`403 FORBIDDEN: 角色「${session.roleLabel}」无权复制功能区`);
    const srcFloor = this.spatial.floors.find((f) => f.id === sourceFloorId);
    const srcZones = this.spatial.zones.filter((z) => z.floorId === sourceFloorId);
    if (!srcFloor || srcZones.length === 0) return 0;
    let added = 0;
    for (const tid of targetFloorIds) {
      if (tid === sourceFloorId) continue;
      const tFloor = this.spatial.floors.find((f) => f.id === tid);
      if (!tFloor) continue;
      const existingNames = new Set(this.spatial.zones.filter((z) => z.floorId === tid).map((z) => z.name));
      for (const sz of srcZones) {
        const cleanBase = sz.name.replace(new RegExp(`^${srcFloor.name}\\s*`, 'i'), '');
        const nextName = `${tFloor.name} ${cleanBase}`.trim();
        if (existingNames.has(nextName)) continue;
        this.spatial.zones.push({
          id: `zone-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`,
          floorId: tid,
          name: nextName,
          category: sz.category,
        });
        existingNames.add(nextName);
        added += 1;
      }
    }
    if (added > 0) this.persistSpatial();
    this.record('REST', 'copyZonesToFloors', 'POST /api/v1/zones/copy', { sourceFloorId, targetCount: targetFloorIds.length, added });
    return added;
  }

